param([ValidateSet('x86','x64')][string]$Platform)
$ErrorActionPreference='Stop'
if (!$Platform) {
  foreach ($arch in @('x86','x64')) {
    & powershell.exe -NoProfile -File $PSCommandPath -Platform $arch
    if ($LASTEXITCODE -ne 0) { throw "Host availability test failed for $arch" }
  }
  exit 0
}
$repoRoot=Split-Path $PSScriptRoot -Parent
. (Join-Path $PSScriptRoot 'assert_native_architecture.ps1')
$source=Join-Path $repoRoot '.deps/dxvk-remix'
. (Join-Path $source 'bridge/build_common.ps1')
SetupVS -Platform $Platform -VcVarsVer '14.29'
$testDir=Join-Path $repoRoot ".deps/steam-availability-$Platform"
New-Item -ItemType Directory -Force $testDir | Out-Null
Push-Location $testDir
try {
  & cl.exe /nologo /std:c++17 /EHsc /O2 /W4 /WX "/I$source/bridge/src/server" "/I$source/bridge/src/util" "$repoRoot/tests/steam_availability_diagnostics.cpp" /Fe:availability-test.exe
  if ($LASTEXITCODE -ne 0) { throw 'Availability diagnostic compilation failed' }
  Assert-NativeArchitecture -Path (Join-Path $testDir 'availability-test.exe') -Architecture $Platform
  & .\availability-test.exe
  if ($LASTEXITCODE -ne 0) { throw 'Availability diagnostic test failed' }
} finally { Pop-Location }
